<div class="section-intro"><div><p class="eyebrow">ADMINISTRATION</p><h2>Comptes et rôles</h2><p class="muted">L’administrateur contrôle les accès au stock et à la caisse.</p></div></div><div class="user-admin-layout"><section class="panel form-panel"><p class="eyebrow">NOUVEAU COMPTE</p><h3>Ajouter un utilisateur</h3><form method="post" action="<?= BASE_URL ?>/index.php?page=utilisateur-save" class="data-form"><div class="form-grid"><label>Nom<input required name="nom"></label><label>Prénom<input name="prenom"></label></div><label>Email professionnel<input required type="email" name="email"></label><label>Mot de passe<input required type="password" minlength="8" name="mot_de_passe"><small>8 caractères minimum.</small></label><label>Rôle<select required name="role_id"><?php foreach ($roles as $role): ?><option value="<?= e($role['id']) ?>"><?= e($role['nom']) ?> — <?= e($role['description']) ?></option><?php endforeach; ?></select></label><button class="button button-primary" type="submit">Créer le compte</button></form></section><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">COMPTES ACTIFS</p><h3>Utilisateurs enregistrés</h3></div></div><div class="table-wrap"><table><thead><tr><th>Utilisateur</th><th>Email</th><th>Rôle</th><th>Statut</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><strong><?= e(trim($user['prenom'] . ' ' . $user['nom'])) ?></strong><small>Créé le <?= date('d/m/Y', strtotime($user['cree_le'])) ?></small></td><td><?= e($user['email']) ?></td><td><span class="status status-<?= $user['role_nom'] === 'Administrateur' ? 'ok' : 'warning' ?>"><?= e($user['role_nom']) ?></span></td><td><?= $user['actif'] ? 'Actif' : 'Inactif' ?></td></tr><?php endforeach; ?></tbody></table></div></section></div><section class="role-legend"><div><strong>Administrateur</strong><span>Accès complet: inventaire, mouvements, caisse et utilisateurs.</span></div><div><strong>Vendeur</strong><span>Tableau de bord et mouvements uniquement.</span></div><div><strong>Dépôt</strong><span>Mêmes droits que le vendeur: tableau de bord et mouvements.</span></div></section>
